class Solution {
    public int countPoints(String rings){
        int[] mask=new int[10];
        for(int i=0;i<rings.length();i+=2){
            int bit=rings.charAt(i)=='R'?1:rings.charAt(i)=='G'?2:4;
            mask[rings.charAt(i+1)-'0']|=bit;
        }
        int answer=0;
        for(int value:mask)if(value==7)answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countPoints(rings:String):Int{
        val mask=IntArray(10);
        for(i in rings.indices step 2){
            val bit=when(rings[i]){
                'R'->1;
                'G'->2;
                else->4
            };
            val rod=rings[i+1]-'0';
            mask[rod]=mask[rod] or bit
        };
        return mask.count{
            it==7
        }
    }
}

